 files['midi-machine-release.js']='window.MC_RELEASES=[{"version": "2.15", "date": "2026-10-21", "changes": [{"en": "MACRO now shows each algorithm’s number (0–46) underneath its name, on a second or third line. All 47 layouts fit without clipping. The existing BACK/reset reference, algorithm order and sound are preserved. Includes the per-track filter and all previous machine-card and DX features.", "fr": "MACRO affiche maintenant le numero0–46 sous le nom de chaque algorithme, sur une deuxieme ou troisieme ligne. Les47affichages tiennent sans troncature. Reference BACK/reset, ordre et son conserves. Filtre par piste et fonctions precedentes de cartes machines et DX inclus."}]}, {"version": "2.14", "date": "2026-10-21", "changes": [{"en": "MACRO now displays its 47 algorithm names instead of numbers. Long names use two lines in the smaller native font so every label fits. Algorithm order, sound and saved values stay the same. Includes the per-track filter, new machine cards, original Wizard hat and saved DX toggle.", "fr": "MACRO affiche maintenant les noms de ses47algorithmes au lieu des nombres. Les noms longs utilisent deux lignes avec la petite police native pour tenir a l ecran. Ordre des algorithmes, son et valeurs sauvegardees identiques. Filtre par piste, nouvelles cartes machines, chapeau Wizard original et DX sauvegarde conserves."}]}, {"version": "2.13", "date": "2026-10-21", "changes": [{"en": "The twelve added machines now have distinct STR, DEX and MAG character profiles. Eleven get angular initial icons; Sample Wizard keeps its original hat and two-line title. The six stock machine cards stay the same. Includes the per-track filter, LTC/SIL menu values and saved DX toggle, Off by default.", "fr": "Les douze machines ajoutees ont des profils STR, DEX et MAG distincts. Onze recoivent des icones d initiales anguleuses ; Sample Wizard garde son chapeau et son titre sur deux lignes. Les six cartes stock restent identiques. Filtre par piste, valeurs LTC/SIL et DX sauvegarde, Off par defaut, conserves."}]}, {"version": "2.12", "date": "2026-10-21", "changes": [{"en": "Main includes the per-track filter and the saved DX diagnostic toggle in Mod Setup, Off by default. Enable DX for the P/O/N popup after beat repeat. Mute Latch is shown as LTC and Silent pad mode as SIL so the values fit. Includes the CHORD Attack retrigger fade, MIDI Swing encoder and note-release fixes.", "fr": "Le principal inclut le filtre par piste et le diagnostic DX sauvegarde dans Mod Setup, Off par defaut. Activez DX pour le popup P/O/N apres beat repeat. Mute Latch devient LTC et le mode pads Silent devient SIL pour eviter le chevauchement. Inclut le raccord CHORD Attack et les correctifs du potard Swing MIDI et des relachements de notes."}]}, {"version": "2.11", "date": "2026-10-21", "changes": [{"en": "MIDI Out now has nine assignable CC knobs, stock Chance/Swing controls and timing, and keyboard arpeggiation with A. On. MIDI LFO values are visible, Speed updates held notes, and Destination browsing sends no modulation while editing. TRACK + FUNC latch timing is reliable. Machine selection shows Sample above Wizard with the right-side hat. User-tested filter build, no diagnostics.", "fr": "MIDI Out propose neuf potards CC assignables, Chance/Swing stock avec timing, et arpege clavier avec A. On. Valeurs LFO MIDI visibles, Speed agit sur les notes tenues et parcourir Destination ne transmet aucune modulation pendant l edition. TRACK + FUNC entre de facon fiable en mute verrouille. Selection de machine : Sample au-dessus de Wizard, chapeau a droite. Version avec filtre testee par l utilisateur, sans diagnostic."}]}, {"version": "2.10", "date": "2026-10-21", "changes": [{"en": "ACID output is 6 dB louder, with DRIVE and synth behavior preserved. Main includes the per-track filter and all previous MIDI, Slice and USB fixes. No diagnostics. AveyCole tested the sound and reported no crash with beat repeat in this build.", "fr": "Sortie ACID augmentÃ©e de 6 dB, avec DRIVE et comportement du synthÃ© conservÃ©s. Le principal inclut le filtre par piste et tous les correctifs MIDI, Slice et USB prÃ©cÃ©dents. Aucun diagnostic. AveyCole a testÃ© le son et ne signale aucun crash avec beat repeat dans cette version."}]}, {"version": "2.09", "date": "2026-10-21", "changes": [{"en": "Fix computer-to-Cycles USB audio breaking up or sounding distorted in 6ch mode. The return audio buffer is enlarged while six-track transmission keeps its existing queue and timing. User reported that the test worked; native send/return and saved-mode checks pass. All prior features and the per-track filter remain included. No diagnostics in main.", "fr": "Correction du retour audio USB ordinateur vers Cycles hachÃ© ou distordu en mode 6ch. Tampon de rÃ©ception agrandi ; file et timing de lâ€™envoi six pistes conservÃ©s. Test signalÃ© fonctionnel par lâ€™utilisateur ; envoi/retour natifs et mode sauvegardÃ© vÃ©rifiÃ©s. Fonctions prÃ©cÃ©dentes et filtre par piste conservÃ©s. Aucun diagnostic dans le principal."}]}, {"version": "2.08", "date": "2026-10-21", "changes": [{"en": "Main now includes the approved Slice playback and ChordKeys MIDI fixes with the per-track filter. MIDI LFO menus start Wav, Mul, Dst, Dep; hold LFO and turn an assigned CC knob to assign its destination, then adjust depth. LFO Speed controls the open MIDI LFO. Updated shortcut guide. Diagnostic removed for main.", "fr": "Le principal inclut les correctifs Slice et ChordKeys MIDI approuves, avec filtre par piste. Menus LFO MIDI : Wav, Mul, Dst, Dep ; maintenir LFO et tourner un CC assigne choisit la destination, puis regle la profondeur. LFO Speed controle le LFO MIDI ouvert. Guide actualise. Diagnostic retire du principal."}]}];\n'
